  var a = anodes[Math.random() < 0.5 ? 0 : 1];
  var side = Math.random();
  var x, y;
  if (side < 0.5) { x = a.x + 10 + Math.random() * (ANODE_W - 20); y = ANODE_BOT - 5 - Math.random() * 25; }
  else if (side < 0.75) { x = a.x - 4 - Math.random() * 8; y = ANODE_BOT - 20 - Math.random() * 60; }
  else { x = a.x + ANODE_W + 4 + Math.random() * 8; y = ANODE_BOT - 20 - Math.random() * 60; }
  var r = 2 + Math.random() * 3.5;
  var el = bubbleLayer.circle(r * 2).center(x, y).fill('#fff').attr({ opacity: 0.92 });
  bubbles.push({ el: el, x: x, y: y, vy: 0.5 + Math.random() * 0.8, r: r });
}

function initIons() {
  for (var i = 0; i < 10; i++) {
    var type = i % 2 === 0 ? 'al' : 'o';
    var el = ionLayer.circle(6).center(CAV_L + 20, 380).fill(type === 'al' ? '#2b6fd6' : '#d63b3b').attr({ opacity: 0.85 });
    ions.push({ el: el, x: CAV_L + 30 + Math.random() * (CAV_R - CAV_L - 60), y: 370 + Math.random() * 80, type: type, tx: 0, ty: 0, retarget: true });
  }
}
initIons();

function retargetIon(o) {
  if (o.type === 'al') { o.tx = CAV_L + 40 + Math.random() * (CAV_R - CAV_L - 80); o.ty = CAT_TOP - 4; }
  else { var a = anodes[Math.random() < 0.5 ? 0 : 1]; o.tx = a.cx + (Math.random() - 0.5) * 60; o.ty = ANODE_BOT - 10; }
  o.retarget = false;
}

var lastSpawn = 0;
function tick(ts) {
  if (running && current > 0) {
    // spawn bubbles at rate ~ current
    var rate = current / 100;
    if (Math.random() < rate * 0.9) spawnBubble();
    if (Math.random() < rate * 0.6) spawnBubble();
    // move bubbles up
    for (var i = bubbles.length - 1; i >= 0; i--) {
      var b = bubbles[i];
      b.y -= b.vy * (0.5 + rate);
      b.x += (Math.random() - 0.5) * 0.6;
      if (b.y < CRUST_Y + 6) { b.el.remove(); bubbles.splice(i, 1); }
      else b.el.center(b.x, b.y);
    }
    // move ions
    for (var j = 0; j < ions.length; j++) {
      var o = ions[j];
      if (o.retarget) retargetIon(o);
      var dx = o.tx - o.x, dy = o.ty - o.y, d = Math.sqrt(dx * dx + dy * dy);
      var sp = (0.6 + rate * 1.4);
      if (d < sp) { o.retarget = true; }
      else { o.x += dx / d * sp; o.y += dy / d * sp; }
      o.el.center(o.x, o.y);
    }
  }
  requestAnimationFrame(tick);
}
requestAnimationFrame(tick);

// ===================== demo step player =====================
var steps = [
  { t: 'The cell at rest', n: 'Identify the structure: carbon anodes suspended in molten cryolite electrolyte above a carbon cathode floor, with a molten aluminum layer collecting between them and a crust sealing the surface.', cur: 50, run: false },
  { t: 'Electrolysis in motion', n: 'Start the animation: Al³⁺ is reduced to liquid aluminum at the cathode while O²⁻ is oxidized at the anodes, producing the rising O₂/CO/CO₂ bubbles that surround each anode.', cur: 50, run: true },
  { t: 'More current, more product', n: 'Drag the current slider up and down: bubble formation accelerates and the molten aluminum layer thickens at high current, and both processes stop at zero — rate tracks current directly.', cur: 90, run: true }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('appliedCurrentInput').value = s.cur;
  document.getElementById('appliedCurrentVal').value = s.cur;
  update_appliedCurrent(s.cur);
  if (running !== s.run) trigger_electrolysisAnimation();
  document.getElementById('demoNarration').textContent = s.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + '/' + steps.length;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }
applyStep(0);

window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

