  else if (side < 0.75) { x = ax - 4 - Math.random() * 10; y = ANODE_BOT - 20 - Math.random() * 60; }
  else { x = ax + ANODE_W + 4 + Math.random() * 10; y = ANODE_BOT - 20 - Math.random() * 60; }
